<?php declare(strict_types=1); ?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rezervasyonlarım</title><style>body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:1050px;margin:35px auto;padding:0 18px}.item{background:white;border:1px solid #e7ece8;border-radius:12px;padding:17px;margin:12px 0;display:flex;justify-content:space-between;gap:16px}.muted{color:#6d796f;font-size:13px}@media(max-width:600px){.item{display:block}}</style></head><body><main class="wrap"><h1>İlan rezervasyonları</h1><?php foreach($bookings as $b): ?><article class="item"><div><strong><?= e($b['title']) ?></strong><p class="muted"><?= e($b['guest_name']) ?> · <?= e($b['guest_email']) ?></p><p class="muted"><?= e($b['check_in']) ?> – <?= e($b['check_out']) ?> · <?= (int)$b['guests'] ?> misafir</p><small><?= e($b['booking_code']) ?></small></div><div><strong><?= e(number_format((float)$b['total'],0,',','.')) ?> <?= e($b['currency']) ?></strong><p><?= e($b['status']) ?></p><a href="/account/messages/<?= (int)$b['id'] ?>">Misafirle mesajlaş</a></div></article><?php endforeach; ?><?php if(!$bookings): ?><p>Henüz rezervasyon talebi yok.</p><?php endif; ?><p><a href="/vendor">Ev sahibi paneli</a></p><?php require APP_ROOT . '/views/site/partials/logout-button.php'; ?></main></body></html>